import React from 'react';
import { Composition } from 'remotion';
import { compositions } from './registry';

// Safe default fallback component if zero compositions exist
const DefaultFallback: React.FC = () => (
  <div style={{ flex: 1, backgroundColor: '#090812', color: '#ffffff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'monospace' }}>
    Studio NARA
  </div>
);

/**
 * Compositions come from ./registry.ts, a static list generated by
 * scripts/studio-compose.mjs.
 *
 * Do not switch this to import.meta.glob: the Remotion CLI bundles this file
 * with webpack, where that Vite-only helper throws "{}.glob is not a function"
 * and every render fails before the first frame. The Screening Room keeps its
 * own glob because it runs inside Vite.
 */
export const RemotionRoot: React.FC = () => {
  return (
    <>
      {compositions.map(({ meta, component }) => (
        <Composition
          key={meta.compName}
          id={meta.compName}
          component={component as React.ComponentType<any>}
          durationInFrames={meta.frames ?? Math.round((meta.duration ?? 10) * (meta.fps ?? 30))}
          fps={meta.fps ?? 30}
          width={meta.width ?? 1080}
          height={meta.height ?? 1920}
        />
      ))}
      {compositions.length === 0 && (
        <Composition
          id="Default"
          component={DefaultFallback}
          durationInFrames={150}
          fps={30}
          width={1080}
          height={1920}
        />
      )}
      {compositions.length > 0 && (
        <Composition
          id="MainVideo"
          component={compositions[0].component as React.ComponentType<any>}
          durationInFrames={compositions[0].meta.frames ?? 300}
          fps={compositions[0].meta.fps ?? 30}
          width={compositions[0].meta.width ?? 1080}
          height={compositions[0].meta.height ?? 1920}
        />
      )}
    </>
  );
};
